// 🔐 ENV VARS — Auto-loaded from env-config.js (generated by build.js)
// Production: Vercel env vars se aate hain
// Local: .env file se aate hain
const SUPABASE_URL = (window.NEXI_ENV && window.NEXI_ENV.SUPABASE_URL) || '';
const SUPABASE_KEY = (window.NEXI_ENV && window.NEXI_ENV.SUPABASE_ANON_KEY) || '';

// ⚠️ Safety check — agar env vars load nahi hue to warn karein
if (!SUPABASE_URL || !SUPABASE_KEY) {
    console.error('❌ CRITICAL: Supabase credentials not loaded!');
    console.error('   - Production: Check Vercel env vars');
    console.error('   - Local: Check .env file + run "node build.js"');
    console.error('   - Also: Ensure <script src="env-config.js"></script> is loaded BEFORE supabase-config.js');
}

// Supabase client (CDN se aata hai — HTML mein script tag lagayenge)
let supabaseClient = null;

// Initialize function — jab bhi zaroorat ho call karein
function initSupabase() {
    if (supabaseClient) return supabaseClient;
    if (typeof supabase === 'undefined') {
        console.error('❌ Supabase CDN not loaded!');
        return null;
    }
    if (!SUPABASE_URL || !SUPABASE_KEY) {
        console.error('❌ Cannot init Supabase — missing credentials');
        return null;
    }
    supabaseClient = supabase.createClient(SUPABASE_URL, SUPABASE_KEY);
    return supabaseClient;
}

// ============================================================
// SUPABASE AUTH HELPERS (Phase B2 — Migration)
// ============================================================

// ------------------------------------------------------------
// 1. SIGN UP — Naya user register karein
// ------------------------------------------------------------
async function signUpUser(email, password, metadata = {}) {
    try {
        const sb = initSupabase();
        if (!sb) return { error: { message: 'Supabase init failed' } };

        const { data, error } = await sb.auth.signUp({
            email: email.toLowerCase().trim(),
            password: password,
            options: {
                data: metadata,
                emailRedirectTo: window.location.origin + '/payment-pending'
            }
        });

        if (error) {
            console.error('signUpUser error:', error);
            return { error };
        }

        console.log('✅ signUpUser success:', data.user?.email);
        return { data };
    } catch (err) {
        console.error('signUpUser exception:', err);
        return { error: { message: err.message || 'Unknown error' } };
    }
}

// ------------------------------------------------------------
// 2. SIGN IN — User login karein
// ------------------------------------------------------------
async function signInUser(email, password) {
    try {
        const sb = initSupabase();
        if (!sb) return { error: { message: 'Supabase init failed' } };

        const { data, error } = await sb.auth.signInWithPassword({
            email: email.toLowerCase().trim(),
            password: password
        });

        if (error) {
            console.error('signInUser error:', error);
            return { error };
        }

        console.log('✅ signInUser success:', data.user?.email);
        return { data };
    } catch (err) {
        console.error('signInUser exception:', err);
        return { error: { message: err.message || 'Unknown error' } };
    }
}

// ------------------------------------------------------------
// 3. SIGN OUT — User logout karein
// ------------------------------------------------------------
async function signOutUser() {
    try {
        const sb = initSupabase();
        if (!sb) return { error: { message: 'Supabase init failed' } };

        const { error } = await sb.auth.signOut();
        if (error) {
            console.error('signOutUser error:', error);
            return { error };
        }

        console.log('✅ signOutUser success');
        return { success: true };
    } catch (err) {
        console.error('signOutUser exception:', err);
        return { error: { message: err.message || 'Unknown error' } };
    }
}

