async function logVisit(page = 'index', ipAddress = null) {
    try {
        const sb = initSupabase();
        if (!sb) return { error: 'Supabase init failed' };

        const today = new Date().toISOString().split('T')[0];
        const ua = navigator.userAgent || '';
        const payload = { page: page, user_agent: ua, visited_date: today };
        if (ipAddress) payload.ip_address = ipAddress;

        const { data, error } = await sb.from('visits').insert([payload]).select().single();
        if (error) { console.error('logVisit error:', error); return { error }; }
        return { data };
    } catch (err) {
        console.error('logVisit exception:', err);
        return { error: err };
    }
}

async function getTodayVisits() {
    try {
        const sb = initSupabase();
        if (!sb) return 0;
        const today = new Date().toISOString().split('T')[0];
        const { count, error } = await sb.from('visits').select('*', { count: 'exact', head: true }).eq('visited_date', today);
        if (error) { console.error('getTodayVisits error:', error); return 0; }
        return count || 0;
    } catch (err) {
        console.error('getTodayVisits exception:', err);
        return 0;
    }
}

async function getVisitsGroupedByDate(limit = 30) {
    try {
        const sb = initSupabase();
        if (!sb) return [];
        const { data, error } = await sb.from('visits').select('visited_date, ip_address').order('visited_date', { ascending: false }).limit(5000);
        if (error) { console.error('getVisitsGroupedByDate error:', error); return []; }

        const grouped = {};
        (data || []).forEach(v => {
            if (!v.visited_date) return;
            if (!grouped[v.visited_date]) grouped[v.visited_date] = { total: 0, ips: new Set() };
            grouped[v.visited_date].total++;
            if (v.ip_address) grouped[v.visited_date].ips.add(v.ip_address);
        });

        return Object.keys(grouped).sort().reverse().slice(0, limit).map(date => ({
            stat_date: date,
            total_visits: grouped[date].total,
            unique_visitors: grouped[date].ips.size
        }));
    } catch (err) {
        console.error('getVisitsGroupedByDate exception:', err);
        return [];
    }
}

